#include <stdio.h>
#include <limits.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int dp[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        int x = i;
        int best = INT_MAX;

        while (x > 0) {
            int d = x % 10;
            x /= 10;

            if (d == 0) continue;

            int cand = dp[i - d];
            if (cand < best) best = cand;
        }

        dp[i] = best + 1;
    }

    printf("%d\n", dp[n]);
    return 0;
}
